package Q6;
import java.util.*;
record Patient(String name,int severity,long arrival){public String toString(){return name+"(S"+severity+")";}}
public class Triage{private long counter=0;private final PriorityQueue<Patient>queue=new PriorityQueue<>(Comparator.comparingInt(Patient::severity).thenComparingLong(Patient::arrival));void admit(String n,int s){if(s<1||s>5)throw new IllegalArgumentException("Severity must be 1..5");queue.add(new Patient(n,s,counter++));}Patient next(){return queue.poll();}public static void main(String[]x){Triage er=new Triage();er.admit("Ravi",3);er.admit("Meena",1);er.admit("John",3);er.admit("Asha",5);er.admit("Kumar",1);er.admit("Lata",2);StringBuilder b=new StringBuilder();Patient p;while((p=er.next())!=null)b.append(p).append(' ');System.out.println(b.toString().trim());}}
